def run_tests(namespace):
    passed = failed = 0
    for name, func in list(namespace.items()):
        if name.startswith("test_") and callable(func):
            try:
                func()
            except AssertionError:
                print("FAIL", name)
                failed += 1
            except Exception as error:
                print("ERROR", name, type(error).__name__)
                failed += 1
            else:
                print("PASS", name)
                passed += 1
    print(f"итого: {passed} пройдено, {failed} упало")


def double(x):
    return x * 2


def test_double_int():
    assert double(4) == 8


def test_double_str():
    assert double("ab") == "abab"


def test_double_zero():
    assert double(0) == 1


def test_double_list():
    assert double([1]) == [1, 1]


run_tests(globals())
